"""Generate conservative reference-design report from V35.1 evidence; not CNC release."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];O=R/'exports/generated/widebody-v351'
def read(n):return json.loads((O/(n+'.json')).read_text())
m=read('mass-counts');n=read('nesting');a=read('attachment-audit');small=read('small-part-audit');c=read('assembly-complexity');g=read('geometry');p=read('packaging')
checks={k:read(k) for k in ['geometry','validation','continuous-motion','conservative-validation','browser-validation']}
assert all(d['pass'] for d in checks.values())
reg=read('manufacturing-register');parts=reg['parts']
# Relative constant-section beam screen, not a material/load certification.
r=592.65/564
structure={'clear_span_ratio':r,'same_total_central_load_stress_ratio':r,'same_total_central_load_deflection_ratio':r**3,'same_load_per_length_stress_ratio':r**2,'same_load_per_length_deflection_ratio':r**4,'section_or_support_removal':False,'scope':'Conservative planning of width-spanning panels/crossmembers; exact panel support differs. No claim of unchanged numerical safety factor. Actual wood modulus/strength and load test HOLD.'}
(O/'structural-planning.json').write_text(json.dumps(structure,indent=2)+'\n')
groups={'Main shell':lambda x:x in ['SIDE_L','SIDE_R','FRONT','REAR','FLOOR','BACKBOX_BASE'] or x.startswith(('FLOOR_CLEAT','CandidateLegBlock')),'Playfield support':lambda x:x.startswith(('PF_','FrontLanding')),'Internal shelves':lambda x:x.startswith('SHELF_'),'Crossmembers':lambda x:x.startswith('CROSS_'),'Backbox shell/supports':lambda x:x in ['BB_SideL','BB_SideR','BB_Top','BB_Floor','BB_RearFrame'] or 'ParkingPad' in x,'Monitor':lambda x:x.startswith('BB_MONITOR'),'DMD/speakers':lambda x:x=='BB_DMD_SPEAKER_PANEL','Acrylic seats/retainer':lambda x:x.startswith('BB_GLASS'),'Doors/fan blanks':lambda x:x=='REAR_DOOR' or x.startswith(('BB_Door','BB_Hinge','BB_Center','BB_FanBlank'))}
principles=['Captured shell assembly; ours keeps floor ledges and solid leg load spreaders.','Holder fitted parallel to glass; ours retains accepted open cradles, wooden dowel and SW02 landings.','No equivalent three-shelf detail established in reviewed public guide; owner retains service shelves and broad supports.','No equivalent three-crossmember detail established; owner protects transverse stiffness and guide bearing.','Planar floor/side/top assembly; ours retains one-face joints, rear access and accepted fold structure.','Fixed plate/front monitor service adopted; separate stops retain three times the proposed blind-guide bearing.','Simple front panel adopted; actual display/speaker cuts held.','Simple edge seating and removable upper retention; acrylic follows owner decision.','Rear service access retained; ordinary hardware; hinge backing and optional upper blanks retain real functions.']
comparison=[]
for (name,fn),desc in zip(groups.items(),principles):comparison.append({'assembly':name,'our_wood_pieces':sum(fn(x['source_component']) for x in parts),'functional_comparison':desc,'Tukkari_source':'https://www.tukkari.com/advisor/assembly-guide-widebody-vpin-cabinet-premium-flat-pack','unjustified_difference_identified':False,'Tukkari_part_count':None})
(O/'tukkari-comparison.json').write_text(json.dumps(comparison,indent=2)+'\n')
lines=['# V35.1 — standard widebody, conservative refinement','','HEAD BEFORE: `11822cb2dc9c7c7b511348df860cb76196d641be`. HEAD AFTER: the commit containing this report (Git is authoritative).','','Reference architecture passes the recorded geometric gates. This is not purchased-part compatibility certification or a manufacturing release. CNC remains BLOCKED. V35/V34.3 unpromoted outputs are study evidence only.','','## Dimensional and commercial decision','','- Body **628.65 mm**, nominal inside **592.65 mm**. Length **1308.10 mm** retained; no hard commercial length conflict established. Backbox **780 × 723.9 mm**, depth and local internal shapes unchanged; assembly translation X+14.325 mm. Side overhang **75.675 mm**. WPC Y1066.8/Z508 unchanged.','- Commercial lockdown **A-17996 / A-16055**; receiver **A-16773-1**, compatible historical alternative **A-9174-4**. No custom lockdown/receiver. Catalogue width/class establishes an architectural candidate, never hole authority.','- Available receiver body reserve **520 × 42 × 40 mm**, additional operating space **388.65 × 42 × 15 mm**, hand/tool approach **90 × 42 × 85 mm** clear modeled occupied objects. These are independently modeled available volumes, NOT measured vendor geometry or a guessed latch trajectory. Actual receiver withdrawal, tab engagement and latch travel must be measured before CNC.','- Siderails are OPTIONAL, zero in minimum BOM. Original slim envelope stops before backbox; a purchased long SKU may require verified trimming (82.2375 mm in the reference study). Glass works without rail. No integral-rail architecture.','- Primary glass is locally cut **5 mm tempered**; reference603.25 ×1092.20 mm, final cutNULL. Actual side-channel profile must accept5mm;3/16in compatibility is not assumed. Side slot reference7.05mm deep leaves10.95mm outer skin; production slot width/depthNULL.','- Rear **03-8091-2 class** channel uses ordinary screws on existing horizontal RearBearingShelf with local angled support. Two integral R2 lands added to the existing member; no separate wood rail. Reference screw screen:10mm front/side margins,16.128mm local stock,12mm pilot embedment, zero pilot-outside-wood/head-glass interference. Count, centers, head and pilot are NULL/HOLD. Tool access passes before backbox assembly or folded90° with glass/matrix removed.','- Rear support angle **9.90666925365°** derived from glass faces; whole backbox floor remains horizontal. Display parallel to glass:0° difference, **7.5 /7.5 /7.5 mm** front/center/rear planning gap. M025528.65mm retains22mm landing edge distance; dowel588.65mm; SW02X72/556.65,Y245.','','## Retained structure and small-part audit','','All three CROSS members, all three SHELF members, guides, shelf supports, M006, SW01×4, SW02×2, open cradles and PC_BASE retained. Protected fixed-section parts compare exactly after inverse placement. Crossmember/shelf lateral spans regenerate without section reduction. No drawer added. Backbox simplified internals remain rigidly unchanged.','','No part-count target. **66 wood /60 CNC plywood /6 solid /45 families**, unchanged count. **33 small pieces KEEP**. Integrated0; retired0; added0. The optional fan blanks have a sealing/dust role for unused upper stations; they are not required in passive-grille mode. Old integral-siderail requirement is retired from the promotion path, not a wood part.','','| Part / family | Decision and reason |','|---|---|']
for x in small:lines.append(f"| {x['ID']} · {x['name']} | KEEP — {x['rationale']} |")
lines+=['','The full 66-row attachment audit records parent, attachment, load, assembly and service value. Parking pads retain36mm insert/shaft depth instead of forcing the parked shaft through18mm floor. Monitor stops retain216mm² bearing each versus72mm² for a blind4mm guide stop. Hinge cleats preserve backing and axis. Acrylic lower seat remains replaceable and independent of DMD removal; upper strip provides positive fold retention.','','## Structural planning limit','',f"No support or section was deleted. Increased nominal span ratio is{r:.6f}. For an ideal same-section beam under the same central force, stress ratio{r:.4f}, deflection ratio{r**3:.4f}; at equal distributed load/length, ratios{r**2:.4f}/{r**4:.4f}. These are relative planning sensitivities, not load certification. It would be false to claim an unchanged numerical safety factor solely from B-rep validity. Retaining all supports is the conservative response; physical material/load qualification remains mandatory.",'','## Tukkari-first functional review','','Public [premium assembly guide](https://www.tukkari.com/advisor/assembly-guide-widebody-vpin-cabinet-premium-flat-pack) reviewed2026-10-06: established shell/holder/front interfaces inform the design. The guide treats siderails as optional and illustrates screw-fixed rear glass channel. Its dimensions/counts were not copied. No proprietary geometry imported.','','| Assembly | Our wood pieces | Functional comparison / justification |','|---|---:|---|']
for x in comparison:lines.append(f"| {x['assembly']} | {x['our_wood_pieces']} | {x['functional_comparison']} |")
lines+=['','Counts are grouped functional subsets, not claimed Tukkari BOM counts. No public equivalence was invented for our shelves/crossmembers. Detailed source register: [V35.1 public references](../library/references/v351-standard-parts.md).','','## Material, nesting and packing','',f"Actual finished B-rep wood mass at550/650/750kg/m³: **{m['wood_LOW_kg']:.3f} /{m['wood_NOMINAL_kg']:.3f} /{m['wood_HIGH_kg']:.3f} kg**. Nominal change+{m['delta_nominal_kg']:.3f}kg. Glass reference{m['glass_reference_mass_kg']:.3f}kg separate. Hardware mass UNKNOWN, not zero. Only12/18mm plywood; solid blocks are separate.",'','| Stock | Pieces | Sheets preliminary | Outer area m² | Utilization | Unused full-sheet area m² |','|---|---:|---:|---:|---:|---:|']
for t,d in n.items():lines.append(f"| {t}mm | {d['pieces']} | {d['sheet_count']} | {d['outer_contour_area_m2']:.6f} | {d['utilization_outer_percent']:.2f}% | {d['unused_full_sheet_outer_m2']:.6f} |")
lines+=['','**2×18mm recovered;1×12mm.** Deterministic four-order MaxRects rectangle study, actual contours shown;2500×1600 sheets,20mm border,15mm spacing. Long piece axis aligned to sheet long grain. No strength reduction; small pieces occupy residual zones. Largest free rectangles are in nesting.json and may overlap, so their areas must not be summed. Unused area includes border/spacing/offcuts, not all reusable stock. This is not production nesting.','','| Bundle | External mm | Nominal wood kg | HIGH +1kg allowance |','|---|---|---:|---:|']
for b in p['bundles']:lines.append(f"| {b['id']} | {' × '.join(f'{v:.1f}' for v in b['external_mm'])} | {b['nominal_wood_kg']:.3f} | {b['high_gross_kg']:.3f} |")
lines+=['','All four bundles remain≤25kg HIGH planning including1kg packaging allowance. Hardware separate; no glass/electronics in wood bundles. Physical packaging qualification pending.','','## Assembly, service and cost','',f"Manual **{c['steps_before']}→{c['steps_after']} steps**; explicit alignment/measurement action steps **{len(c['manual_alignment_steps_before'])}→{len(c['manual_alignment_steps_after'])}**. These are document counts, not measured labor time. Dry fit SAME; existing T-guide pilots/hinge-cleat templates and F06 reinforcement remain inherited qualification holds. No builder is instructed to improvise structural placement. Labor SAME planning; actual hardware-change/time count unresolved.",'','Commercial compatibility IMPROVED; plywood projection2×18+1×12; overall qualitative cost direction NEUTRAL/uncertain without quotations (avoids bespoke lockdown fabrication). No invented price.','','Normal fold: remove main glass and matrix, release/park rear locks, close/latch doors, fold. Backbox acrylic and front DMD/speaker panel remain installed; no routine disconnection. Raised playfield support remains outside scope/HOLD. 42C5 and43QN93D thin reference envelopes pass;77mm-deep40S5K is an explicit failed sensitivity case, not a compatible TV.','','## Validation','','| Evidence | Passing checks |','|---|---:|']
for k,d in checks.items():lines.append(f"| {k}.json | {sum(x['pass'] for x in d['checks'])}/{len(d['checks'])} |")
lines+=['',f"Manufacturing reconstruction maximum difference **{m['reconstruction_max_mm3']} mm³**.32 native-CAD review images; offline desktop/tablet, EN/PT-BR and palettes retained. Collision/kinematic checks prove the modeled reference state only; purchased hardware and human/structural qualification remain open.",'','## Remaining release gates','','Purchase and measure matched lockdown/receiver (body, underside tabs, latch travel, mounting, withdrawal/tool access); side/rear channels and5mm glass fit; optional rail if selected; actual plywood lot and coupon; fit regeneration; VESA/display, buttons/USB, leg/WPC/shooter, DMD/speakers, landing hardware; inherited placement/manual-operation holds; physical load/nudge/glass-edge/thermal qualification; primary raised-playfield support. **CNC FULL-SHEET RELEASE BLOCKED.**','']
text='\n'.join(lines);(R/'docs/STANDARD_WIDEBODY_V351.md').write_text(text);(O/'README.md').write_text(text)
print('V351 REPORT',sum(len(d['checks']) for d in checks.values()),'checks')
